import { Link } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

export default function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#work', label: 'Work' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    if (href.startsWith('#')) {
      e.preventDefault();
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
      setIsMobileMenuOpen(false);
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled
          ? 'bg-background/95 backdrop-blur-sm border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-6xl mx-auto px-6 md:px-10">
        <div className="flex h-16 md:h-20 items-center justify-between">
          {/* Wordmark */}
          <Link
            to="/"
            className="font-heading text-xl md:text-2xl font-semibold tracking-tight text-foreground hover:text-primary transition-colors duration-200"
          >
            AM
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navItems.map((item) => (
              <a
                key={item.href}
                href={item.href}
                onClick={(e) => handleNavClick(e, item.href)}
                className="group relative text-sm font-medium tracking-wide text-foreground/70 hover:text-foreground transition-colors duration-200"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-200 group-hover:w-full" />
              </a>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border/50 py-4 bg-background/95 backdrop-blur-sm">
            <nav className="flex flex-col gap-1">
              {navItems.map((item) => (
                <a
                  key={item.href}
                  href={item.href}
                  onClick={(e) => handleNavClick(e, item.href)}
                  className="text-sm font-medium text-foreground/70 hover:text-foreground py-3 px-2 transition-colors"
                >
                  {item.label}
                </a>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  const handleBackToTop = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-10 py-6">
        <div className="flex flex-col sm:flex-row justify-between items-center gap-3">
          <p className="text-xs text-muted-foreground tracking-wide">
            © {currentYear} Alex Morgan. All rights reserved.
          </p>
          <a
            href="#"
            onClick={handleBackToTop}
            className="text-xs text-muted-foreground hover:text-foreground transition-colors duration-200 tracking-wide"
          >
            Back to top ↑
          </a>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter } from 'lucide-react';

// ─── Animation variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const, delay },
  }),
};

const staggerContainer = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12 } },
};

const wordFadeUp = {
  hidden: { opacity: 0, y: 32 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.4, ease: 'easeOut' as const },
  },
};

// ─── Component ────────────────────────────────────────────────────────────────

export default function HomePage() {
  const nameWords = ['Alex', 'Morgan'];

  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer & Developer</title>
        <meta
          name="description"
          content="Alex Morgan is a designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col justify-center px-6 md:px-10 pt-20 pb-16 max-w-6xl mx-auto">
        {/* Decorative thin vertical line */}
        <div className="absolute left-6 md:left-10 top-32 bottom-32 w-px bg-border hidden lg:block" />

        <div className="lg:pl-12">
          {/* Eyebrow */}
          <motion.p
            className="text-sm font-medium tracking-[0.2em] text-primary uppercase mb-8"
            initial="hidden"
            animate="visible"
            custom={0}
            variants={fadeUp}
          >
            Portfolio
          </motion.p>

          {/* Name — staggered word animation */}
          <motion.h1
            className="font-heading text-[clamp(4rem,14vw,11rem)] font-semibold leading-[0.9] tracking-tight text-foreground mb-8"
            variants={staggerContainer}
            initial="hidden"
            animate="visible"
          >
            {nameWords.map((word) => (
              <motion.span
                key={word}
                className="block"
                variants={wordFadeUp}
              >
                {word}
              </motion.span>
            ))}
          </motion.h1>

          {/* Tagline */}
          <motion.p
            className="text-lg md:text-xl text-foreground/60 font-light max-w-md leading-relaxed"
            initial="hidden"
            animate="visible"
            custom={0.55}
            variants={fadeUp}
          >
            Designer &amp; Developer crafting thoughtful digital experiences.
          </motion.p>

          {/* Scroll indicator */}
          <motion.div
            className="mt-16 flex items-center gap-3 text-xs tracking-[0.15em] text-muted-foreground uppercase"
            initial="hidden"
            animate="visible"
            custom={0.75}
            variants={fadeUp}
          >
            <span className="block w-8 h-px bg-border" />
            Scroll
          </motion.div>
        </div>

        {/* Decorative corner mark */}
        <div className="absolute bottom-16 right-10 hidden md:flex flex-col items-end gap-1 opacity-20">
          <div className="w-12 h-px bg-foreground" />
          <div className="w-6 h-px bg-foreground" />
        </div>
      </section>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="py-24 md:py-32 px-6 md:px-10 max-w-6xl mx-auto">
        {/* Section label */}
        <motion.p
          className="text-xs tracking-[0.2em] text-muted-foreground uppercase mb-12"
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          custom={0}
          variants={fadeUp}
        >
          01 — About
        </motion.p>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-16 items-start">
          {/* Left: bold statement */}
          <motion.div
            className="lg:col-span-4"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            custom={0.1}
            variants={fadeUp}
          >
            <h2 className="font-heading text-3xl md:text-4xl font-semibold leading-tight text-foreground">
              Building at the intersection of design and code.
            </h2>
          </motion.div>

          {/* Right: photo + bio */}
          <motion.div
            className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-10 items-start"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            custom={0.2}
            variants={fadeUp}
          >
            {/* Portrait */}
            <div className="relative aspect-[3/4] overflow-hidden bg-muted">
              <img
                src="/airo-assets/images/pages/about/portrait"
                alt="Alex Morgan"
                className="w-full h-full object-cover"
                width={600}
                height={700}
              />
              {/* Thin accent border offset */}
              <div className="absolute -bottom-2 -right-2 w-full h-full border border-primary pointer-events-none" />
            </div>

            {/* Bio text */}
            <div className="flex flex-col gap-5 text-foreground/70 leading-relaxed text-base">
              <p>
                I'm a multidisciplinary designer and developer with over 6 years of experience
                building products that are both beautiful and functional.
              </p>
              <p>
                My work spans brand identity, interface design, and full-stack development — I
                believe the best digital experiences emerge when design and engineering think
                together from the start.
              </p>
              <p>
                Currently open to freelance projects and full-time opportunities. Based in San
                Francisco, working globally.
              </p>
              <div className="pt-2">
                <a
                  href="#contact"
                  onClick={(e) => {
                    e.preventDefault();
                    document.querySelector('#contact')?.scrollIntoView({ behavior: 'smooth' });
                  }}
                  className="inline-flex items-center gap-2 text-sm font-medium text-foreground hover:text-primary transition-colors duration-200 group"
                >
                  Get in touch
                  <span className="block w-6 h-px bg-current transition-all duration-200 group-hover:w-10" />
                </a>
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Thin divider */}
      <div className="max-w-6xl mx-auto px-6 md:px-10">
        <div className="h-px bg-border" />
      </div>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="py-24 md:py-32 px-6 md:px-10 max-w-6xl mx-auto">
        {/* Section label */}
        <motion.p
          className="text-xs tracking-[0.2em] text-muted-foreground uppercase mb-12"
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          custom={0}
          variants={fadeUp}
        >
          02 — Contact
        </motion.p>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-end">
          {/* Left: heading + email */}
          <motion.div
            className="lg:col-span-7"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            custom={0.1}
            variants={fadeUp}
          >
            <h2 className="font-heading text-3xl md:text-5xl font-semibold leading-tight text-foreground mb-10">
              Let's make something great together.
            </h2>

            <a
              href="mailto:hello@alexmorgan.com"
              className="group inline-flex items-center gap-3 text-xl md:text-2xl font-medium text-foreground hover:text-primary transition-colors duration-200"
            >
              hello@alexmorgan.com
              <span className="block w-0 h-px bg-primary transition-all duration-300 group-hover:w-8 self-end mb-1" />
            </a>
          </motion.div>

          {/* Right: social icons */}
          <motion.div
            className="lg:col-span-5 flex flex-col gap-6"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            custom={0.2}
            variants={fadeUp}
          >
            <p className="text-xs tracking-[0.15em] text-muted-foreground uppercase">
              Find me on
            </p>
            <div className="flex items-center gap-6">
              {[
                {
                  href: 'https://github.com',
                  icon: Github,
                  label: 'GitHub',
                },
                {
                  href: 'https://linkedin.com',
                  icon: Linkedin,
                  label: 'LinkedIn',
                },
                {
                  href: 'https://twitter.com',
                  icon: Twitter,
                  label: 'Twitter / X',
                },
              ].map(({ href, icon: Icon, label }) => (
                <a
                  key={label}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={label}
                  className="group flex items-center gap-2 text-foreground/50 hover:text-primary transition-all duration-150"
                >
                  <Icon
                    size={22}
                    className="transition-transform duration-150 group-hover:scale-110"
                  />
                  <span className="text-sm text-foreground/40 group-hover:text-primary transition-colors duration-150 hidden sm:inline">
                    {label}
                  </span>
                </a>
              ))}
            </div>
          </motion.div>
        </div>
      </section>
    </>
  );
}

